package com.taxcalculator.connector;
import com.taxcalculator.domain.*; import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.databind.node.*; import org.springframework.beans.factory.annotation.Autowired; import java.time.*; import java.util.*;
abstract class AbstractMockConnector implements VehicleSourceConnector {
 @Autowired ObjectMapper mapper; abstract String id(); abstract String eventType();
 public String sourceId(){return id();} public Set<LookupType> supportedLookupTypes(){return Set.of(LookupType.VIN,LookupType.PLATE,LookupType.PLATE_AND_COUNTRY);} public Set<String> supportedCountries(){return Set.of("*");}
 public SourceFetchResult fetch(LookupInput input){String key=input.value().toUpperCase(); if(key.contains("TIMEOUT"))return new SourceFetchResult(SourceQueryStatus.TIMEOUT,null,"Simulated provider timeout"); if(key.contains("NODATA"))return SourceFetchResult.noData(); if(key.contains("FAIL"))return new SourceFetchResult(SourceQueryStatus.FAILURE,null,"Simulated provider failure"); ObjectNode root=mapper.createObjectNode(); ArrayNode events=root.putArray("events"); ObjectNode first=events.addObject(); first.put("type",eventType()); first.put("date","2021-06-15"); if(eventType().equals("MILEAGE_READING"))first.put("km", key.contains("ROLLBACK")?145000:120000); if(eventType().equals("DAMAGE_RECORD")){first.put("severity","MODERATE");first.put("description","Reported front-end damage");} if(eventType().equals("INSURANCE_RECORD"))first.put("status","INSURED"); if(key.contains("ROLLBACK")&&eventType().equals("MILEAGE_READING")){ObjectNode later=events.addObject();later.put("type",eventType());later.put("date","2023-08-10");later.put("km",110000);} return SourceFetchResult.success(root);}
}
